import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
public class AssessmentPrivacyChecks{
 static int checks;static void check(String name,boolean ok){if(!ok)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 public static void main(String[] args)throws Exception{
  String reportId="123e4567-e89b-12d3-a456-426614174000",itemId="123e4567-e89b-12d3-a456-426614174001",subject="SUB-11111111-2222-3333-4444-555555555555";
  Map<String,Object> person=map("id","local-person","name","李测试","code","105000","birth","1990-02-03","org","某某煤矿机构","age",36,"sex","男","job","采煤机司机","exposure","煤尘；噪声","phone","13800138000");
  String text="李测试；工号：105000；电话：13800138000；身份证：110101199002030011；出生日期：1990-02-03；某某煤矿机构；某某医院；检查医生：王某；未见明显异常。";
  Map<String,Object> report=map("id",reportId,"revision",1,"examDate","2026-01-01","institution","某某医院","items",Arrays.asList(map("id",itemId,"name","胸片","value","未见明显异常","unit","","referenceRange","","page",2,"abnormal","")),"conclusions",Arrays.asList(map("text",text,"page",2,"label","结论","evidenceId","local-evidence")),"advice",Arrays.asList(map("text","结合临床复查，手机号13800138000","page",2)),"files",Arrays.asList(map("name","李测试105000.pdf","objectRef","D:/update/private.pdf")),"fieldValues",Arrays.asList(map("field_key","phone","value_raw","13800138000")));
  Map<String,Object> source=map("person",person,"report",report,"history",Arrays.asList(report),"assessmentRules",map("scope_code","org:private","id","local-rule-id"));String before=new ObjectMapper().writeValueAsString(source);AssessmentPrivacy.Context context=AssessmentPrivacy.prepare(source,subject);String json=new ObjectMapper().writeValueAsString(context.model);
  int privateIndex=0;for(String value:Arrays.asList("李测试","105000","13800138000","110101199002030011","1990-02-03","某某煤矿机构","某某医院","王某",reportId,itemId,"local-person","local-evidence","org:private","D:/update"))check("private_literal_removed_"+(++privateIndex),!json.contains(value));
  check("age_sex_job_and_exposure_are_retained",json.contains("36")&&json.contains("男")&&json.contains("采煤机司机")&&json.contains("煤尘；噪声"));check("clinical_result_retained_without_exam_date",json.contains("未见明显异常")&&!json.contains("2026-01-01"));check("calendar_date_fields_are_not_sent",!json.contains("examDate")&&!json.contains("examDateRaw")&&!json.contains("assessmentDate"));check("calendar_dates_removed_from_free_text",!new AssessmentPrivacy.Redactor(source).text("体检2022年9月3日，检查2022/09/03，总检2022.9.3；血糖6.8 mmol/L").contains("2022")&&new AssessmentPrivacy.Redactor(source).text("血糖6.8 mmol/L").contains("6.8 mmol/L"));check("temporary_subject_is_sent",subject.equals(context.model.get("subject_ref")));check("only_allowlisted_person_fields_are_sent",((Map<?,?>)context.model.get("person")).keySet().equals(new HashSet<>(Arrays.asList("subject_ref","age","sex","job","exposure"))));check("item_alias_maps_back_locally",itemId.equals(context.itemIds.get("OBS-C-0001")));check("archive_snapshot_is_not_modified",before.equals(new ObjectMapper().writeValueAsString(source)));
  AiExamChecks.Fake model=new AiExamChecks.Fake();Map<String,Object> response=model.generate(map("task_type","health_assessment","archive_context",context.model));Map<String,Object> parsed=AiHealthReport.parse(str(response.get("output")),source,subject);check("anonymous_result_relinks_original_item",itemId.equals(((Map<?,?>)((List<?>)parsed.get("indicator_analysis")).get(0)).get("item_id")));check("local_template_refills_patient_name",AiHealthReport.plain(parsed,source).contains("李测试"));
  Map<String,Object> wrong=new ObjectMapper().readValue(str(response.get("output")),Map.class);wrong.put("subject_ref","SUB-OTHER-PERSON");try{AiHealthReport.parse(new ObjectMapper().writeValueAsString(wrong),source,subject);throw new AssertionError();}catch(EhrException e){check("mismatched_subject_is_rejected","AI_ASSESSMENT_FORMAT_INVALID".equals(e.getMessage()));}
  check("medical_number_is_not_blindly_removed_as_employee_number","105000".equals(new AssessmentPrivacy.Redactor(source).text("105000")));System.out.println("PASS assessment privacy checks: "+checks);
 }
}
